CREATE TABLE conversations(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id),title VARCHAR(255) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());CREATE TABLE conversation_messages(id BIGSERIAL PRIMARY KEY,conversation_id BIGINT NOT NULL REFERENCES conversations(id),role VARCHAR(30) NOT NULL,content TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());CREATE INDEX idx_conversation_messages ON conversation_messages(conversation_id,created_at);CREATE TABLE stored_files(id BIGSERIAL PRIMARY KEY,original_filename VARCHAR(255) NOT NULL,object_key VARCHAR(500) UNIQUE NOT NULL,size BIGINT NOT NULL,checksum VARCHAR(128) NOT NULL,created_by BIGINT NOT NULL REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),orphaned_at TIMESTAMPTZ);ALTER TABLE file_transfer_steps ADD CONSTRAINT fk_file_transfer_stored_file FOREIGN KEY(stored_file_id) REFERENCES stored_files(id);CREATE TABLE audit_events(id BIGSERIAL PRIMARY KEY,user_id BIGINT REFERENCES users(id),action VARCHAR(100) NOT NULL,entity_type VARCHAR(100) NOT NULL,entity_id BIGINT,metadata JSONB,created_at TIMESTAMPTZ NOT NULL DEFAULT now());CREATE INDEX idx_audit_user_time ON audit_events(user_id,created_at);